     1	import { InvalidFunnelError } from '../errors/InvalidFunnelError';
     2	import { StageNotFoundError } from '../errors/StageNotFoundError';
     3	
     4	/**
     5	 * A stage of a funnel.
     6	 *
     7	 * `capacity` is the maximum number of leads the stage can hold. Absent means no
     8	 * limit; `0` means the stage is closed.
     9	 */
    10	export interface Stage {
    11	  id: string;
    12	  name: string;
    13	  capacity?: number;
    14	}
    15	
    16	/**
    17	 * Funnel entity.
    18	 *
    19	 * A funnel is an ordered list of stages, validated once at construction: a
    20	 * funnel that exists is a funnel that is well formed.
    21	 *
    22	 * The stages are not exposed. The funnel answers questions about them instead
    23	 * of handing out `capacity?: number`, so no caller can read an absent limit and
    24	 * a zero limit as the same falsy value.
    25	 */
    26	export class Funnel {
    27	  private readonly stages: Stage[];
    28	
    29	  constructor(
    30	    public readonly id: string,
    31	    stages: Stage[]
    32	  ) {
    33	    if (stages.length === 0) {
    34	      throw new InvalidFunnelError('a funnel needs at least one stage');
    35	    }
    36	
    37	    const seenIds = new Set<string>();
    38	    for (const stage of stages) {
    39	      if (stage.id.trim().length === 0) {
    40	        throw new InvalidFunnelError('a stage id cannot be empty');
    41	      }
    42	      if (seenIds.has(stage.id)) {
    43	        throw new InvalidFunnelError(`duplicated stage id "${stage.id}"`);
    44	      }
    45	      if (!isValidCapacity(stage.capacity)) {
    46	        throw new InvalidFunnelError(
    47	          `stage "${stage.id}" has capacity ${stage.capacity}, expected a non-negative integer`
    48	        );
    49	      }
    50	      seenIds.add(stage.id);
    51	    }
    52	
    53	    // Copied so that mutating the array or the stage objects after construction
    54	    // cannot change a funnel that has already been validated.
    55	    this.stages = stages.map((stage) => ({ ...stage }));
    56	  }
    57	
    58	  /** New leads always enter here. */
    59	  firstStageId(): string {
    60	    return this.stages[0].id;
    61	  }
    62	
    63	  hasStage(stageId: string): boolean {
    64	    return this.stages.some((stage) => stage.id === stageId);
    65	  }
    66	
    67	  stageName(stageId: string): string {
    68	    return this.stageOrFail(stageId).name;
    69	  }
    70	
    71	  /**
    72	   * Whether the stage can hold one more lead, given how many it holds now.
    73	   *
    74	   * The occupancy is supplied by the caller on purpose: the funnel knows the
    75	   * limit and the repository knows the occupancy, so only the use case sees
    76	   * both. This is a question about the limit, not the capacity rule itself.
    77	   */
    78	  canAcceptOneMore(stageId: string, currentOccupancy: number): boolean {
    79	    const { capacity } = this.stageOrFail(stageId);
    80	
    81	    if (capacity === undefined) {
    82	      return true;
    83	    }
    84	
    85	    return currentOccupancy < capacity;
    86	  }
    87	
    88	  private stageOrFail(stageId: string): Stage {
    89	    const stage = this.stages.find((candidate) => candidate.id === stageId);
    90	
    91	    if (stage === undefined) {
    92	      throw new StageNotFoundError(stageId);
    93	    }
    94	
    95	    return stage;
    96	  }
    97	}
    98	
    99	function isValidCapacity(capacity: number | undefined): boolean {
   100	  return capacity === undefined || (Number.isInteger(capacity) && capacity >= 0);
   101	}
