     4	
     5	/**
     6	 * Lead entity.
     7	 *
     8	 * A lead represents a potential customer inside a funnel. It is identified by
     9	 * its phone number, and it knows which stage it currently sits in.
    10	 *
    11	 * The stage is only reachable through `moveTo`, which guarantees the lead never
    12	 * enters an invalid state whoever calls it. `isAt` answers the same question
    13	 * without applying any rule, so a caller that needs to decide which error to
    14	 * raise first can ask before acting.
    15	 */
    16	export class Lead {
    17	  private _stageId: string;
    18	
    19	  constructor(
    20	    public readonly phone: PhoneNumber,
    21	    public readonly name: string,
    22	    stageId: string
    23	  ) {
    24	    if (name.trim().length === 0) {
    25	      throw new InvalidLeadError('name cannot be empty');
    26	    }
    27	
    28	    this._stageId = stageId;
    29	  }
    30	
    31	  get stageId(): string {
    32	    return this._stageId;
    33	  }
    34	
    35	  isAt(stageId: string): boolean {
    36	    return this._stageId === stageId;
    37	  }
    38	
    39	  moveTo(targetStageId: string): void {
    40	    if (this.isAt(targetStageId)) {
    41	      throw new InvalidStageTransitionError(
    42	        `Cannot move lead ${this.phone.value} from stage ${this._stageId} ` +
    43	          `to stage ${targetStageId}: it is already there`
    44	      );
    45	    }
    46	
    47	    this._stageId = targetStageId;
    48	  }
    49	}
