     1	import { InvalidPhoneNumberError } from '../errors/InvalidPhoneNumberError';
     2	
     3	/**
     4	 * Phone number value object.
     5	 *
     6	 * A phone number is the identity of a lead: two leads are the same lead when
     7	 * their canonical form is the same string.
     8	 *
     9	 * Accepted format: a "+" followed by 8 to 15 digits. Separators are ignored
    10	 * because they are presentation, not data: what decides identity is the "+"
    11	 * and the digits, so "+52 55 1234 5678", "+52-55-1234-5678" and
    12	 * "+525512345678" are the same number.
    13	 *
    14	 * Everything else is rejected, including numbers written without a country
    15	 * code. Presentation is normalized, meaning is never inferred: turning a local
    16	 * number into a canonical one requires a default region, which is workspace
    17	 * configuration this service never receives, so the ambiguity is given back to
    18	 * the caller instead of being guessed here.
    19	 */
    20	export class PhoneNumber {
    21	  private static readonly MIN_DIGITS = 8;
    22	  private static readonly MAX_DIGITS = 15;
    23	
    24	  public readonly value: string;
    25	
    26	  constructor(input: string) {
    27	    if (typeof input !== 'string') {
    28	      throw new InvalidPhoneNumberError(String(input));
    29	    }
    30	
    31	    const candidate = [...input].filter((character) => !isSeparator(character)).join('');
    32	    const digits = candidate.slice(1);
    33	
    34	    const startsWithPlus = candidate.startsWith('+');
    35	    const isAllDigits = [...digits].every(isDigit);
    36	    const hasAcceptedLength =
    37	      digits.length >= PhoneNumber.MIN_DIGITS && digits.length <= PhoneNumber.MAX_DIGITS;
    38	
    39	    if (!startsWithPlus || !isAllDigits || !hasAcceptedLength) {
    40	      throw new InvalidPhoneNumberError(input);
    41	    }
    42	
    43	    this.value = candidate;
    44	  }
    45	
    46	  equals(other: PhoneNumber): boolean {
    47	    return this.value === other.value;
    48	  }
    49	
    50	  toString(): string {
    51	    return this.value;
    52	  }
    53	}
    54	
    55	const SEPARATORS = ' -().';
    56	
    57	function isSeparator(character: string): boolean {
    58	  return SEPARATORS.includes(character);
    59	}
    60	
    61	function isDigit(character: string): boolean {
    62	  return character >= '0' && character <= '9';
    63	}
