      // MAP.md §3 — "una transicion es una relacion binaria - origen y destino.
      // `InvalidStageTransitionError(stageId)` no podria decir de donde venia el lead."
      const lead = new Lead(phone(), 'Ada', NEW);
      lead.moveTo(CONTACTED);

